def learned_silu_bwd(res, grad_output):
    x, slope, sigmoid_x = res
    grad_input = grad_output * slope * (sigmoid_x + x * sigmoid_x * (1.0 - sigmoid_x))
    grad_slope_full = grad_output * x * sigmoid_x
